import {routeObjective} from './objective-routing.js?v=5.11.0';
import {listeningEpilogue} from './new-game-plus.js?v=5.6.0';
import {endingPages} from './campaign-content.js?v=5.18.0';
import {selectedJourneyLead,journeyPurpose,homeConversation,homecomingPages} from './campaign-purpose.js?v=5.18.0';
import {cityAnswerEpilogue} from './city-answer.js?v=5.18.0';
/** Story-earned onboarding. Legacy saves keep their already acquired crew and kit. */
export const STORY_VERSION=1;
export const REWARDS=[null,
 {core:'flame',support:'break',slots:2,why:'Rook recovers the furnace pilot; the freed cell relay teaches Break.'},
 {core:'ward',support:'chain',why:'Brass turns the carriage shield into a protective pattern; its linked rails teach Chain.'},
 {core:'tide',support:'link',why:'Riven restores the water pattern. Three rescued districts teach the crew to link their conductors.'},
 {core:'frost',support:'burst',why:'Hesper’s rain bells preserve the cold pattern and a spreading pulse.'},
 {core:'shade',support:'pierce',why:'Mira recovers a hidden archive channel and its piercing carrier.'},
 {core:'volt',support:'echo',slots:3,why:'Veyr reclaims the sky engine’s current and delayed echo. A third conductor socket can now be fitted.'},
 {core:'gale',support:'counter',why:'The living orchard breathes against the engine and answers its blows.'},
 {core:'gravity',support:'field',why:'The fallen Crown exposes the holding field beneath its reactor.'},
 {support:'quick',why:'Lowbank’s evacuation teaches a shorter, lighter casting phrase.'},
 {support:'leech',why:'The last prison train yields a regenerative feedback pattern.'},
 {support:'overdrive',why:'The river memorial reveals the cost of forcing a pattern past its safe limit.'}];
export function earned(world){return world.state.story?.version===STORY_VERSION&&world.state.chronicle?.phase!=='past';}
export function journal(world,id,title,text){const story=world.state.story;if(!story||story.journal.some(e=>e.id===id))return;story.journal.push({id,title,text,chapter:world.state.chapter});}
export function newStory(){return{version:STORY_VERSION,parcel:false,weapon:false,mako:false,slots:0,armor:false,rookAsked:false,firstCore:false,failures:{},rewarded:[],journal:[]};}
export function gainCore(world,id,heroId){const s=world.state;if(!s.cores.includes(id))s.cores.push(id);if(!s.supports.includes('focus'))s.supports.push('focus');if(heroId!==undefined){const h=s.heroes[heroId];h.loadout=[{core:id,support:'focus'}];h.mp=h.maxMp;h.unlockedSlots=1;}s.story.mako=true;s.story.slots=Math.max(1,s.story.slots);}
export function join(world,id){const s=world.state;if(s.recruited.includes(id))return false;s.recruited.push(id);if(s.party.length<3)s.party.push(id);s.heroes[id].hp=s.heroes[id].maxHp;world.callbacks.onScene(world.scene);return true;}
function offerRook(w){w.state.story.rookAsked=true;w.choose('ROOK: I built the regulator on that carriage. They said it was for the heating lines.\nSABLE: Nell’s father was singing. Then he couldn’t make a sound.\nROOK: I saw.\nSABLE: Can you get us inside?\nROOK: Through my workshop. If they trace the hatch, they’ll come for me.\nSABLE: You don’t have to come.\nROOK: I built it, Sable. I’m coming.',[['Open it. Come with me.',()=>{join(w,2);journal(w,'rook','Rook joins','His regulator carried stolen voices. He brings a workshop nail-driver and chooses to help undo what he built.');w.text('ROOK: There’s spare gear in the east locker. Take the pry-staff.\nSABLE: I’ve never used one on a person.\nROOK: Good. Let’s try to keep it that way.\nRook joined the crew. His repair tools are ready to use.');}],['Give me a moment.',()=>{}]]);}
export function settleOpening(w){if(!earned(w)||w.state.mode!=='field')return;const s=w.state,t=s.story;if(w.bit(8323526,0)&&!t.repairReward){t.repairReward=true;s.gold+=20;journal(w,'repair','A promise kept','You repaired the orchestra with Sable’s mother’s reed. Rook paid 20 credits; Nell’s father will sing beside the lantern.');w.notice('Orchestra repaired · 20 credits earned');}if(w.bit(8323526,1)&&!s.recruited.includes(2)&&!t.rookAsked)return offerRook(w);if(w.bit(8323568,3)&&!t.firstCore){
 t.firstCore=true;gainCore(w,'earth',0);journal(w,'earth','A voice beneath the carrier','The reader teaches Sable Earth / Focus. Beneath the prisoner’s voice is a phrase from his mother, recorded after her death. Who has been keeping it?');
 const network='ROOK: Two conductors. One carries a call out. The other should carry an answer back.\nSABLE: Someone at home could tell the works to stop?\nROOK: Or ask for help. Clay holds the pattern; the water line carries it between places. But this carrier is clamped to the intake. It keeps taking.\nSABLE: Then we follow the return.\nROOK: After we open the cells. The district still needs its heat. We have to leave it something that works.';
 journal(w,'network-first','A line that should answer','Rook identifies an outward call and a return conductor. The collector takes voices through the service line; the crew must find a way to restore replies without cutting off the district’s heat.');
 const response=['','IONA: Those people in the cells can still come home. We start with them.','','BRASS: Once they are out, I’ll follow every number on that carriage.','RIVEN: The service plan runs down to the river. I can help trace where the water goes.','MIRA: Keep the date with the phrase. We need the evidence of what was done to it.','VEYR: I can read the transfer marks. I signed enough of them.'][selectedJourneyLead(s)];
 w.callbacks.onMusic(29);w.text(['The clay warms under Sable’s hand. A woman hums three notes.\nSABLE: Play that again.\nROOK: Do you know her?\nSABLE: My mother sang that when she couldn’t sleep.\nROOK: The date on this plate...\nSABLE: She was already dead. Three years.\nROOK: Wrap it up. Nell’s father is still in there. We get him out, and then we find whoever made this copy.\nLearned: Earth / Focus. One pattern socket is available.',...(response?[response]:[]),network]);
}}
export function storyEntry(w,r){if(!earned(w))return false;const t=w.state.story;if(r.key==='home'&&!t.homeSeen){t.homeSeen=true;w.setBit(r.entry_flag_address??w.mission.flag_address,r.entry_bit||0);journal(w,'delivery','One last delivery','Mara has kept Sable’s mother’s tuning reed. Bring it to Rook for the festival; Sable was meant to be home before dark.');w.text(['The last delivery of the day was supposed to take ten minutes. A tuning reed to the festival, an empty case back home. Outside, someone was trying to tune a kettle.','MARA: Rook sent twice for that reed. He says the orchestra won’t stay in tune without it.\nSABLE: He says that about everything he hasn’t fixed yet.\nMARA: Then you’d better give him time. The case comes home tonight.\nSABLE: I know.\nMARA: I’m asking about you, too.']);return true;}if(r.key==='town'&&!t.fairSeen){t.fairSeen=true;w.setBit(r.entry_flag_address,r.entry_bit||0);w.text('CINDERFALL · THE FESTIVAL OF MENDED THINGS\nA kettle rattles in time with six mismatched strings. '+(w.state.recruited.includes(2)?'Rook sets down what he carried and goes to the orchestra’s loose tuning peg.':'Beside the orchestra, Rook is losing an argument with a tuning peg.')+' A little girl saves an empty place by the lantern.');return true;}return false;}
export function canEnterStory(w,next){if(!earned(w))return true;const s=w.state;if(s.chapter===1&&next.location===226&&!w.bit(8323526,1)){w.text('The Kiln service is closed for the festival. Rook is waiting beside the orchestra.');return false;}if(s.chapter===1&&next.key==='town'&&!s.story.parcel){w.text('Mara is waiting by the table. Take the tuning reed before leaving.');return false;}if(s.chapter===1&&['security','console'].includes(next.key)&&(!s.story.weapon||!s.story.firstCore)){w.text('ROOK: East locker for work gear. Clay reader at the west bench.\nWe need both before entering the yard.');return false;}return true;}
export function storyInteraction(w,o){if(!earned(w))return false;const s=w.state,t=s.story,key=w.scene.key;if(key==='home'&&o.type==='npc'&&s.complete){const first=!t.returnedHome;t.returnedHome=true;const pages=homecomingPages(s);journal(w,'home','The case comes home',pages.join('\n\n'));w.text(first?pages:'MARA: The kettle is on. You do not have to be making a delivery to sit down.');return true;}
 if(key==='home'&&o.type==='npc'){if(!t.parcel){t.parcel=true;s.items.tonic+=2;journal(w,'reed','Mother’s tuning reed','Mara entrusted Sable with the reed, along with two home remedies for the road. Rook is waiting in the Commons.');w.text('MARA: Don’t let Rook scrape that reed down. Your mother spent a whole winter getting it right.\nSABLE: He’ll get it back exactly as it is.\nMARA: And take these. You forget to eat when you’re running deliveries.\nReceived: tuning reed and 2 Tonics.\nSABLE: I’ll bring the case back before the kettle boils dry.');}else{const visit=homeConversation(s);if(visit){if(visit.fresh)journal(w,visit.id,visit.title,visit.pages.join('\n\n'));w.text(visit.pages);}else w.text(w.bit(8323526,1)?'MARA: Nell came looking for her father. Do what you can. Your mother never came home on time either.':'MARA: Rook is at the festival orchestra. I will keep the kettle warm.');}return true;}
 if(key==='town'&&o.type==='puzzle'&&o.flag_address===8323526&&o.bit===0){if(!t.parcel){w.text('ROOK: I can mend it, but I need the reed Mara kept for me.');return true;}if(w.bit(8323526,1)&&!s.recruited.includes(2)){offerRook(w);return true;}}
 if(o.type==='portal'&&o.to==='workshop'&&!s.recruited.includes(2)){if(!w.bit(8323526,1))w.text(o.locked||'Meet Nell by the lantern first.');else offerRook(w);return true;}
 if(o.storyEvent==='iona'){w.choose('IONA: Stop. You’re heading for the cells?\nSABLE: A man was taken from the festival. His daughter is waiting for him.\nIONA: Then take me. There are people in there who can barely stand.\nROOK: Can you fight?\nIONA: I can get them home breathing. Can you open the door?',[['We need you.',()=>{join(w,1);gainCore(w,'mend',1);s.heroes[1].learned|=128;s.items.tonic+=2;s.items.ether++;journal(w,'iona','Iona joins','The prison medic brings Mend, two Tonics and an Ether. She is here for her patients, not an adventure.');w.text('IONA: Don’t pull anyone up by the arms. Some of them have been strapped down for days.\nSABLE: We’ll follow your lead.\nIona joined the crew. Mend / Focus is ready.\nIONA: Open the cells. I’ll stay with whoever can’t walk.');}],['I will scout the relay first.',()=>{}]]);return true;}
 if(key==='workshop'&&o.type==='cache'&&o.bit===1){if(t.weapon){w.text('The spare work gear is already packed.');return true;}t.weapon=true;s.heroes[0].gearPower=4;s.heroes[0].power+=4;s.items.tonic++;s.items.ether++;w.setBit(w.flagFor(o),o.bit);journal(w,'gear','Work gear, not a uniform','An insulated pry-staff, a canvas guard wrap, one Tonic and one Ether. Rook’s spare tools are enough to begin.');w.text('ROOK: Loop the wrap through your wrist. If the rail kicks, let the staff go.\nSABLE: What’s in the reader?\nROOK: A plate from the carriage. The west bench still has power. Let’s see what they were carrying.\nReceived: insulated pry-staff, work wrap, 1 Tonic and 1 Ether.\nAttack and Guard are ready.');return true;}
 if(o.type==='patrol'&&w.scene.chapter===1&&(!t.weapon||!t.firstCore)){w.text('ROOK: Not yet. Take the work gear from the east locker, then read the clay at the west bench.');return true;}
 if(o.type==='boss'&&w.scene.chapter===1&&!s.recruited.includes(1)){w.text('SABLE: Those prisoners need treatment as soon as the cells open.\nIona is waiting by the yard entrance. Ask her to come.');return true;}
 return false;}
export function storyReward(w,m){if(!earned(w))return;const s=w.state,t=s.story,r=REWARDS[m.id];t.rewarded??=[];if(t.rewarded.includes(m.id))return;t.rewarded.push(m.id);if(m.id===15)t.armor=false;if(m.id===1){t.armor=true;s.heroes[0].learned|=128;s.heroes[2].learned|=128;s.heroes[0].gearHP=20;s.heroes[0].maxHp+=20;s.heroes[0].hp+=20;journal(w,'coat','A coat freely given','The freed workers give Sable a reinforced coat. This is the first time he wears their colors by choice.');}if(r){if(r.core&&!s.cores.includes(r.core))s.cores.push(r.core);if(r.support&&!s.supports.includes(r.support))s.supports.push(r.support);t.slots=Math.max(t.slots,r.slots||1);journal(w,'reward:'+m.id,'Recovered pattern · '+m.title,r.why);w.notice((r.core?r.core.toUpperCase()+' · ':'')+(r.support?r.support.toUpperCase():'')+(r.slots?' · '+r.slots+' linked sockets':''));}for(const id of s.recruited){const h=s.heroes[id];h.unlockedSlots=t.slots;if(!h.loadout.length){const core=s.cores.includes(['earth','mend','flame','ward','tide','gale','shade'][id])?['earth','mend','flame','ward','tide','gale','shade'][id]:s.cores[0];if(core)h.loadout.push({core,support:'focus'});}while(h.loadout.length<t.slots&&h.loadout.length)h.loadout.push({core:h.loadout[0].core,support:s.supports.includes('break')?'break':'focus'});}journal(w,'chapter:'+m.id,m.title,m.debrief||m.clear);if(MEMORY_PAYOFFS[m.id])journal(w,'memory:'+m.id,'The recovered recording',MEMORY_PAYOFFS[m.id]);}
export function openingObjective(w){if(!earned(w))return null;const s=w.state,t=s.story,objects=w.objects();if(s.complete)return t.returnedHome?null:routeObjective(w,{label:'Bring the reed case home to Mara',scene:2,object:w.scene.key==='home'?objects.find(o=>o.type==='npc'):null});if(s.chapter>1)return null;if(w.scene.key==='home'&&!t.parcel)return{label:'Take the tuning reed from Mara',object:objects.find(o=>o.type==='npc')};if(w.scene.key==='home'&&t.parcel)return{label:'Bring the reed to Rook at the festival',object:objects.find(o=>o.type==='portal')};if(w.scene.key==='town'&&w.bit(8323526,1)&&!s.recruited.includes(2))return{label:'Ask Rook to open the service hatch',object:objects.find(o=>o.type==='puzzle'&&o.bit===0)};if(w.scene.key==='workshop'&&!t.weapon)return{label:'Recover work gear from the east locker',object:objects.find(o=>o.type==='cache'&&o.bit===1)};if(w.scene.key==='workshop'&&!t.firstCore)return{label:'Read the clay at the west bench',object:objects.find(o=>o.type==='puzzle'&&o.bit===3)};if(w.scene.key==='security'&&!s.recruited.includes(1))return{label:'Meet Iona, the prison medic',object:objects.find(o=>o.storyEvent==='iona')};return null;}
export function prepareOpeningData(source){const data=JSON.parse(JSON.stringify(source));const home=data.scenes.find(r=>r.key==='home'),town=data.scenes.find(r=>r.key==='town'),work=data.scenes.find(r=>r.key==='workshop'),yard=data.scenes.find(r=>r.key==='security');const npc=home.objects.find(o=>o.type==='npc');npc.text='MARA: Your mother’s tuning reed is on the table.';const bench=work.objects.find(o=>o.type==='puzzle'&&o.bit===3);bench.effects=[];bench.success='The plate keeps the trapped voices. Beneath them, a familiar phrase begins to answer Sable.';const theft=town.objects.find(o=>o.type==='puzzle'&&o.bit===1);for(const effects of theft.choice_effects||[])for(const effect of effects)if(effect.text)effect.text+='\nNELL: You promised he would get to sing.';yard.objects.push({type:'npc',storyEvent:'iona',sprite:1,xy:[16,52],text:'IONA: Those prisoners are my patients.'});return data;}
export const MEMORY_PAYOFFS={5:'MIRA: Look at the work dates. Same phrase. Same name. Every winter.\nSABLE: They paid her for one festival song.\nMIRA: And kept charging the city to use it after she died.\nSABLE: As if she were still working for them.\nMIRA: As if she could still say yes.',15:'Sable finds the dispatch mark he used as a courier on the copied registrations.\nHe carried the papers without asking what the sealed boxes held. He removes the insignia; the knowledge stays with him.',21:'The crack runs across a row of dates. Under it, Sable finds the original session mark and the later copying records.\nSABLE: She wasn’t here. Not after.\nIONA: No. I’m sorry.\nSABLE: I thought... I kept thinking there might be something we’d missed.\nROOK: There was. They copied what she gave them. That’s what we can stop.\nSABLE: One song. She gave them one song.'};
export function finishStory(w){
 const recognition=cityAnswerEpilogue(w.state);
 w.choose([...recognition,'The city can choose its own voices now.\nOne last phrase remains in Sable’s reed case: the song his mother chose to leave.\nSable must decide what happens to this recording. Neither the city nor the crew is owed another use of it.'],[['Take the song home to Mara.',()=>end(1)],['Let the city hear it once, then end the broadcast.',()=>end(2)]]);
 function end(choice){
  const s=w.state;s.story.finalChoice=choice;s.complete=true;s.chapter=25;
  journal(w,'city-answer','The city answers',recognition.join('\n\n'));
  journal(w,'ending','A voice is not a person',choice===1?'Sable kept the private recording with the family. The city’s future does not require another stolen voice.':'The last phrase played once by choice. Then the broadcast ended; the people below began a song of their own.');
  w.callbacks.onMusic('performance:clay_and_water_complete');const credits=Array.isArray(w.data.campaign.credits)?w.data.campaign.credits:[w.data.campaign.credits],purpose=journeyPurpose(s);
  w.text([choice===1?'Sable closes the case. There is no resurrection inside it, only something freely given.':'For one evening the city listens. When the phrase ends, nobody makes it begin again.',...endingPages(w),...listeningEpilogue(s),...credits,'One delivery remains.\n'+purpose.aim],()=>w.loadScene(2,[21,8]));
 }
}
